import fs from 'node:fs';
import {chromium} from 'playwright';
const base=process.env.URL,sha=process.env.GITHUB_SHA;
if(!base||!sha||!base.includes(sha))throw new Error(`NOT_EXACT_SHA ${base||''} ${sha||''}`);
const out='frozen-final-proof',KEY='wdcc-owner-review-fixture-v3-recovered-media';fs.mkdirSync(out,{recursive:true});
const browser=await chromium.launch({headless:true});const writes=[];
const fail=(n,d={})=>{throw new Error(`${n} ${JSON.stringify(d)}`)};const watch=p=>p.on('request',r=>{if(['POST','PUT','PATCH','DELETE'].includes(r.method()))writes.push({method:r.method(),url:r.url()})});
const vehicles=[{id:'proof-vdp',year:2020,make:'Dodge',model:'Challenger',trim:'SXT',price:24995,mileage:41000,stock:'DGC2020SXT',status:'published',visibility:'public',primary_image_url:'/wdcc-review-media/nissan350z'},{id:'proof-charger',year:2019,make:'Dodge',model:'Charger',trim:'R/T',price:21995,mileage:53000,stock:'DCR2019RT',status:'published',visibility:'public',primary_image_url:'/wdcc-review-media/fordF150'},{id:'proof-camaro',year:2018,make:'Chevrolet',model:'Camaro',trim:'LT',price:20995,mileage:38000,stock:'CCLT2018',status:'published',visibility:'public',primary_image_url:'/wdcc-review-media/hondaPilot'},{id:'proof-jeep',year:2020,make:'Jeep',model:'Grand Cherokee',trim:'Laredo',price:23995,mileage:60000,stock:'JGCL2020',status:'draft',visibility:'public',primary_image_url:'/wdcc-review-media/kiaSportage'},{id:'proof-f150',year:2018,make:'Ford',model:'F-150',trim:'XLT',price:22995,mileage:71000,stock:'FF150XLT2018',status:'published',visibility:'public',primary_image_url:'/wdcc-review-media/toyotaRav4'}];
const session={authenticated:true,name:'Sean',role:'dealer_agent',tenantId:'wdcc',user:{id:'brand-proof',displayName:'Sean',role:'dealer_agent',tenantId:'wdcc'}};const dashboard={summary:{soldThisWeek:7,newToday:12,appointments:5,applications:8,messages:3},inventory:vehicles,leads:[{id:'l1',name:'John Doe',kind:'contact',stage:'new',vehicleInterest:'Challenger',createdAt:new Date().toISOString()}]};
async function wire(p){await p.route('**/api/auth/session**',r=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(session)}));await p.route('**/api/crm/dashboard**',r=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(dashboard)}));await p.route('**/api/inventory**',r=>r.request().method()==='GET'?r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({ok:true,items:vehicles})}):r.abort());await p.route('**/api/inventory/**',r=>r.request().method()==='GET'?r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({ok:true,item:vehicles[0]})}):r.abort())}
async function go(p,path){let r=null;for(let i=0;i<20;i++){const j=path.includes('?')?'&':'?';r=await p.goto(`${base}${path}${j}proof=${Date.now()}-${i}`,{waitUntil:'domcontentloaded',timeout:30000}).catch(()=>null);if(r?.status()===200)return;await p.waitForTimeout(1000)}fail('HTTP',{path,status:r?.status()||0})}
async function ownerHome(p){await go(p,'/?owner-review=1');await p.evaluate(k=>sessionStorage.setItem(k,'1'),KEY);await p.reload({waitUntil:'domcontentloaded',timeout:30000});const b=p.getByRole('button',{name:/skip intro/i});if(await b.count())await b.click().catch(()=>{});await p.locator('.wdcc-header-wordmark').waitFor({state:'visible',timeout:10000});await p.waitForFunction(()=>document.querySelectorAll('.rh-grid>article').length===5,null,{timeout:30000})}
async function shot(p,n){await p.screenshot({path:`${out}/${n}.png`,fullPage:true})}
const result={sha,url:base,desktop:{},mobile:{},dealer:{},writes,pass:false};
try{
 const dc=await browser.newContext({viewport:{width:1440,height:1000},deviceScaleFactor:1}),d=await dc.newPage();watch(d);await ownerHome(d);
 const home=await d.evaluate(()=>{const q=s=>document.querySelector(s),w=q('.wdcc-header-wordmark'),r=w.getBoundingClientRect();return{text:(w.textContent||'').replace(/\s+/g,' ').trim(),w:r.width,h:r.height,main:getComputedStyle(q('.wdcc-header-wordmark>strong')).color,cc:getComputedStyle(q('.wdcc-header-wordmark>strong>span')).color,tag:getComputedStyle(q('.wdcc-header-wordmark>small')).color,headline:[...document.querySelectorAll('.rh-copy h1 span')].map(x=>(x.textContent||'').trim()),colors:[...document.querySelectorAll('.rh-copy h1 span')].map(x=>getComputedStyle(x).color),benefits:getComputedStyle(q('.rh-benefits')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,featured:getComputedStyle(q('.rh-grid')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,cards:q('.rh-grid').children.length,finance:getComputedStyle(q('.rh-steps')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,trust:getComputedStyle(q('.rh-trust-grid')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,overflow:document.documentElement.scrollWidth-innerWidth}});
 if(!home.text.includes('WDCC')||!home.text.includes("WE DON'T CARE CARS")||home.w<125||home.h<54||home.main!=='rgb(255, 255, 255)'||home.cc!=='rgb(242, 31, 50)'||home.tag!=='rgb(255, 255, 255)'||JSON.stringify(home.headline)!==JSON.stringify(['BAD CREDIT?','NO CREDIT?',"WE DON'T CARE."])||JSON.stringify(home.colors)!==JSON.stringify(['rgb(242, 31, 50)','rgb(22, 138, 244)','rgb(255, 255, 255)'])||home.benefits!==4||home.featured!==5||home.cards!==5||home.finance!==4||home.trust!==4||home.overflow>2)fail('DESKTOP_HOME',home);result.desktop.home=home;await shot(d,'desktop-home');
 await go(d,'/vehicle/real-2004-nissan-350z?owner-review=1');await d.locator('.vehicleLayout').waitFor({state:'visible',timeout:15000});const vdp=await d.evaluate(()=>({cols:getComputedStyle(document.querySelector('.vehicleLayout')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,actions:[...document.querySelectorAll('.vehicleActionsPrimary .cta')].map(x=>(x.textContent||'').trim()),photo:!!document.querySelector('.vehiclePhoto img'),overflow:document.documentElement.scrollWidth-innerWidth}));if(vdp.cols!==2||JSON.stringify(vdp.actions)!==JSON.stringify(['SCHEDULE TEST DRIVE','CALL SEAN'])||!vdp.photo||vdp.overflow>2)fail('VDP',vdp);result.desktop.vdp=vdp;await shot(d,'desktop-vdp');
 const dd=await dc.newPage();watch(dd);await wire(dd);await go(dd,'/dealer');await dd.locator('.dealerDashboardLocked').waitFor({state:'visible',timeout:15000});const dash=await dd.evaluate(()=>{const q=s=>document.querySelector(s),top=s=>q(s).getBoundingClientRect().top,img=q('.dcTop .brand>img'),s=getComputedStyle(img),r=img.getBoundingClientRect();return{metrics:getComputedStyle(q('.dashMetrics')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,ops:getComputedStyle(q('.opsCards')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,delta:Math.max(top('.inventoryOverview'),top('.recentVehicles'),top('.activityLocked'))-Math.min(top('.inventoryOverview'),top('.recentVehicles'),top('.activityLocked')),src:img.getAttribute('src'),nw:img.naturalWidth,nh:img.naturalHeight,display:s.display,visibility:s.visibility,opacity:s.opacity,w:r.width,h:r.height,overflow:document.documentElement.scrollWidth-innerWidth}});if(dash.metrics!==6||dash.ops!==4||dash.delta>3||dash.src!=='/wdcc-official-logo.webp'||dash.nw<20||dash.nh<20||dash.display==='none'||dash.visibility==='hidden'||Number(dash.opacity)<.9||dash.w<45||dash.h<45||dash.overflow>2)fail('DEALER_DESKTOP',dash);result.dealer.desktop=dash;await shot(dd,'dealer-desktop');await dc.close();
 const mc=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1}),m=await mc.newPage();watch(m);await ownerHome(m);const mh=await m.evaluate(()=>{const q=s=>document.querySelector(s),w=q('.wdcc-header-wordmark'),r=w.getBoundingClientRect(),grid=q('.rh-grid'),rs=[...grid.children].slice(0,3).map(x=>x.getBoundingClientRect());return{header:q('[data-wdcc-public-chrome="header"]').getBoundingClientRect().height,text:(w.textContent||'').replace(/\s+/g,' ').trim(),w:r.width,h:r.height,cc:getComputedStyle(q('.wdcc-header-wordmark>strong>span')).color,benefits:getComputedStyle(q('.rh-benefits')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,finance:getComputedStyle(q('.rh-steps')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,trust:getComputedStyle(q('.rh-trust-grid')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,visible:rs.filter(x=>x.left<innerWidth&&x.right>0).length,overflow:document.documentElement.scrollWidth-innerWidth}});if(Math.abs(mh.header-64)>2||!mh.text.includes('WDCC')||mh.w<105||mh.h<44||mh.cc!=='rgb(242, 31, 50)'||mh.benefits!==2||mh.finance!==1||mh.trust!==2||mh.visible<2||mh.overflow>2)fail('MOBILE_HOME',mh);result.mobile.home=mh;await shot(m,'mobile-home');
 const md=await mc.newPage();watch(md);await wire(md);await go(md,'/dealer');await md.locator('.dealerDashboardLocked').waitFor({state:'visible',timeout:15000});const dm=await md.evaluate(()=>{const q=s=>document.querySelector(s),img=q('.dcTop .brand>img'),s=getComputedStyle(img),r=img.getBoundingClientRect();return{side:getComputedStyle(q('.dcSide')).display,nav:getComputedStyle(q('.dashMobileNav')).display,metrics:getComputedStyle(q('.dashMetrics')).gridTemplateColumns.split(/\s+/).filter(Boolean).length,src:img.getAttribute('src'),nw:img.naturalWidth,nh:img.naturalHeight,display:s.display,visibility:s.visibility,opacity:s.opacity,w:r.width,h:r.height,overflow:document.documentElement.scrollWidth-innerWidth}});if(dm.side!=='none'||dm.nav!=='grid'||dm.metrics!==2||dm.src!=='/wdcc-official-logo.webp'||dm.nw<20||dm.nh<20||dm.display==='none'||dm.visibility==='hidden'||Number(dm.opacity)<.9||dm.w<38||dm.h<38||dm.overflow>2)fail('DEALER_MOBILE',dm);result.dealer.mobile=dm;await shot(md,'dealer-mobile');await mc.close();
 if(writes.length)fail('WRITES',writes);result.pass=true;fs.writeFileSync(`${out}/result.json`,JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
}finally{await browser.close();}
